-- ============================================================================
-- BANCO DE DADOS: rpg_escola  (versão evoluída - branch projeto-dados-final)
-- SGBD: MySQL 8.0.16 ou superior (necessário para o CHECK ser aplicado)
-- CONTEÚDO: 1. Estrutura | 2. Catálogos | 3. Massa de dados | 4. Conferência
-- Executável a partir de um banco vazio:  mysql -u usuario -p < database.sql
-- ============================================================================

CREATE DATABASE IF NOT EXISTS rpg_escola
    CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE rpg_escola;
SET NAMES utf8mb4;

-- ----------------------------------------------------------------------------
-- PARTE 1: ESTRUTURA
-- ----------------------------------------------------------------------------
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS historico_experiencia;
DROP TABLE IF EXISTS personagem_recompensa;
DROP TABLE IF EXISTS personagem_conquista;
DROP TABLE IF EXISTS missao_realizada;
DROP TABLE IF EXISTS recompensa;
DROP TABLE IF EXISTS conquista;
DROP TABLE IF EXISTS missao;
DROP TABLE IF EXISTS disciplina;
DROP TABLE IF EXISTS personagem;
DROP TABLE IF EXISTS estudante;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE estudante (
    id_estudante INT AUTO_INCREMENT PRIMARY KEY,
    nome  VARCHAR(100) NOT NULL,
    email VARCHAR(100) NOT NULL UNIQUE,
    turma VARCHAR(50)  NOT NULL
);

-- NOVA: permite agrupar missões por matéria
CREATE TABLE disciplina (
    id_disciplina INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(50) NOT NULL UNIQUE
);

CREATE TABLE personagem (
    id_personagem INT AUTO_INCREMENT PRIMARY KEY,
    nome        VARCHAR(100) NOT NULL,
    nivel       INT NOT NULL DEFAULT 1,
    experiencia INT NOT NULL DEFAULT 0,
    classe      VARCHAR(50)  NOT NULL,
    id_estudante INT NOT NULL UNIQUE,                 -- garante o 1:1 com estudante
    CONSTRAINT chk_personagem_nivel CHECK (nivel >= 1),
    CONSTRAINT chk_personagem_exp   CHECK (experiencia >= 0),
    CONSTRAINT fk_personagem_estudante FOREIGN KEY (id_estudante)
        REFERENCES estudante(id_estudante) ON DELETE CASCADE
);

CREATE TABLE missao (
    id_missao INT AUTO_INCREMENT PRIMARY KEY,
    titulo    VARCHAR(100) NOT NULL,
    descricao TEXT,
    dificuldade ENUM('Fácil','Média','Difícil','Lendária') NOT NULL,
    experiencia INT NOT NULL,
    prazo_dias  INT NOT NULL,                         -- NOVO: prazo para concluir
    id_disciplina INT NOT NULL,                       -- NOVO
    CONSTRAINT chk_missao_exp   CHECK (experiencia > 0),
    CONSTRAINT chk_missao_prazo CHECK (prazo_dias > 0),
    CONSTRAINT fk_missao_disciplina FOREIGN KEY (id_disciplina)
        REFERENCES disciplina(id_disciplina)
);

CREATE TABLE conquista (
    id_conquista INT AUTO_INCREMENT PRIMARY KEY,
    nome      VARCHAR(100) NOT NULL,
    descricao TEXT,
    requisito VARCHAR(255),
    categoria ENUM('Missões','Disciplina','Progressão') NOT NULL   -- NOVO
);

CREATE TABLE recompensa (
    id_recompensa INT AUTO_INCREMENT PRIMARY KEY,
    nome      VARCHAR(100) NOT NULL,
    descricao TEXT,
    tipo ENUM('Nota','Privilégio','Item Físico') NOT NULL   -- agora ENUM
);

-- data_registro -> data_inicio; NOVA data_conclusao (NULL enquanto em andamento)
CREATE TABLE missao_realizada (
    id_missao_realizada INT AUTO_INCREMENT PRIMARY KEY,
    id_personagem INT NOT NULL,
    id_missao     INT NOT NULL,
    status ENUM('Em Andamento','Concluída','Falhou') NOT NULL DEFAULT 'Em Andamento',
    data_inicio    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    data_conclusao DATETIME NULL,
    CONSTRAINT chk_mr_datas CHECK (data_conclusao IS NULL OR data_conclusao >= data_inicio),
    CONSTRAINT chk_mr_status CHECK (
        (status = 'Em Andamento' AND data_conclusao IS NULL)
        OR (status <> 'Em Andamento' AND data_conclusao IS NOT NULL)),
    CONSTRAINT fk_mr_personagem FOREIGN KEY (id_personagem)
        REFERENCES personagem(id_personagem) ON DELETE CASCADE,
    CONSTRAINT fk_mr_missao FOREIGN KEY (id_missao)
        REFERENCES missao(id_missao) ON DELETE CASCADE
);

CREATE TABLE personagem_conquista (
    id_personagem INT NOT NULL,
    id_conquista  INT NOT NULL,
    data_desbloqueio DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id_personagem, id_conquista),
    FOREIGN KEY (id_personagem) REFERENCES personagem(id_personagem) ON DELETE CASCADE,
    FOREIGN KEY (id_conquista)  REFERENCES conquista(id_conquista)  ON DELETE CASCADE
);

CREATE TABLE personagem_recompensa (
    id_personagem INT NOT NULL,
    id_recompensa INT NOT NULL,
    data_recebimento DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id_personagem, id_recompensa),
    FOREIGN KEY (id_personagem) REFERENCES personagem(id_personagem) ON DELETE CASCADE,
    FOREIGN KEY (id_recompensa) REFERENCES recompensa(id_recompensa) ON DELETE CASCADE
);

-- NOVA: registra cada ganho ou perda de XP (histórico / ranking por período)
CREATE TABLE historico_experiencia (
    id_historico INT AUTO_INCREMENT PRIMARY KEY,
    id_personagem INT NOT NULL,
    id_missao_realizada INT NULL,
    origem ENUM('Missão','Conquista','Bônus','Penalidade') NOT NULL,
    pontos INT NOT NULL,
    data_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_hx_pontos CHECK (pontos <> 0),
    CONSTRAINT fk_hx_personagem FOREIGN KEY (id_personagem)
        REFERENCES personagem(id_personagem) ON DELETE CASCADE,
    CONSTRAINT fk_hx_mr FOREIGN KEY (id_missao_realizada)
        REFERENCES missao_realizada(id_missao_realizada) ON DELETE SET NULL
);

CREATE INDEX idx_mr_status_data ON missao_realizada (status, data_conclusao);
CREATE INDEX idx_hx_data ON historico_experiencia (data_hora);


-- ----------------------------------------------------------------------------
-- PARTE 2: DADOS (catálogos)
-- ----------------------------------------------------------------------------





-- ----------------------------------------------------------------------------
-- PARTE 3: DADOS (estudantes, personagens e operações)
-- ----------------------------------------------------------------------------







































































-- ----------------------------------------------------------------------------
-- PARTE 4: CONFERÊNCIA (registros por tabela e total)
-- ----------------------------------------------------------------------------
SELECT 'estudante' AS tabela, COUNT(*) AS registros FROM estudante
UNION ALL SELECT 'disciplina', COUNT(*) FROM disciplina
UNION ALL SELECT 'personagem', COUNT(*) FROM personagem
UNION ALL SELECT 'missao', COUNT(*) FROM missao
UNION ALL SELECT 'conquista', COUNT(*) FROM conquista
UNION ALL SELECT 'recompensa', COUNT(*) FROM recompensa
UNION ALL SELECT 'missao_realizada', COUNT(*) FROM missao_realizada
UNION ALL SELECT 'personagem_conquista', COUNT(*) FROM personagem_conquista
UNION ALL SELECT 'personagem_recompensa', COUNT(*) FROM personagem_recompensa
UNION ALL SELECT 'historico_experiencia', COUNT(*) FROM historico_experiencia
UNION ALL SELECT 'TOTAL', (SELECT COUNT(*) FROM estudante) + (SELECT COUNT(*) FROM disciplina)
  + (SELECT COUNT(*) FROM personagem) + (SELECT COUNT(*) FROM missao) + (SELECT COUNT(*) FROM conquista)
  + (SELECT COUNT(*) FROM recompensa) + (SELECT COUNT(*) FROM missao_realizada)
  + (SELECT COUNT(*) FROM personagem_conquista) + (SELECT COUNT(*) FROM personagem_recompensa)
  + (SELECT COUNT(*) FROM historico_experiencia);